const wantsTools = turn.finishReason === "tool_calls" && turn.toolCalls.length > 0;
if (!wantsTools) {
    // JSON action protocol: parse <tool>/fenced action blocks from text.
    if (!textActionsEnabled || !toolInvoke)
        break;
    const actions = parsePaperclipActionBlocks(turn.assistantText);
    if (actions.length === 0) {
        // Model finished without ever acting (classic "narrated the
        // work" failure). Give it exactly one corrective nudge.
        if (actionsExecuted === 0 && !noActionNudgeUsed && turn.assistantText.trim().length > 0) {
            noActionNudgeUsed = true;
            await onLog("stdout", `\n[paperclip-groq] No action blocks in reply; sending one corrective nudge.\n`);
            messages.push({
                role: "user",
                content: "You ended your reply without emitting any <tool> action block, so NOTHING was executed on the control plane. " +
                    "If your task requires action, emit exactly one <tool> block now. " +
                    "At minimum, record a disposition with paperclip_update_issue_status before finishing.",
            });
            continue;
        }
        break;
    }
    const resultLines = [];
    for (const action of actions) {
        await onLog("stdout", `\n[paperclip_action] ${action.tool}(${stringifyToolResult(action.args).slice(0, 500)})\n`);
        let result;
        try {
            result = await toolInvoke(action.tool, action.args);
        }
        catch (err) {
            result = { ok: false, error: err instanceof Error ? err.message : String(err) };
        }
        actionsExecuted++;
        if (action.tool === "paperclip_update_issue_status" && result && result.ok !== false) {
            dispositionRecorded = true;
        }
        const resultText = stringifyToolResult(result);
        await onLog("stdout", `[paperclip_result] ${resultText.slice(0, 500)}\n`);
        resultLines.push(`${action.tool} -> ${resultText}`);
    }
    messages.push({
        role: "user",
        content: "Action results:\n" +
            resultLines.join("\n") +
            "\nContinue if more actions are needed, otherwise summarize and finish without emitting further blocks." +
            (dispositionRecorded
                ? ""
                : " Reminder: you have not yet recorded a disposition; call paperclip_update_issue_status (done / in_review / blocked) before finishing."),
    });
    if (iter === MAX_TOOL_ITERATIONS - 1) {
        hitIterationCap = true;
    }
    continue;
}
